import{_ as r,o as t,c as u,a3 as i,j as e,a as s}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/vorbereitung/gruppenprozesse-noten-fehlstundensummen-automatisch-berechnen.png",l="/bilder/vorbereitung/gruppenprozesse-noten-einstellungen-fehlstundenerfassung.png",b=JSON.parse('{"title":"Fehlstundensummen automatisch berechnen","description":"","frontmatter":{"title":"Fehlstundensummen automatisch berechnen","source_pageid":1230,"source_revision":5201},"headers":[],"relativePath":"zeugnisse/vorbereitung/fehlstunden-summen-autom-berechnen-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/fehlstunden-summen-autom-berechnen-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),d={name:"zeugnisse/vorbereitung/fehlstunden-summen-autom-berechnen-gruppenprozesse-noten-zeugnisvorbereitung.md"};function o(h,n,g,m,c,p){return t(),u("div",null,[...n[0]||(n[0]=[i('<h1 id="fehlstundensummen-automatisch-berechnen" tabindex="-1">Fehlstundensummen automatisch berechnen <a class="header-anchor" href="#fehlstundensummen-automatisch-berechnen" aria-label="Permalink to &quot;Fehlstundensummen automatisch berechnen&quot;">​</a></h1><p>Summieren Sie tages- oder fachbezogen erfasste Fehlstunden zu Gesamt- und unentschuldigten Fehlstunden. Erneutes Berechnen überschreibt manuelle Änderungen an den Summen.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noten-fehlstundensummen-automatisch-berechnen.png"><img src="'+a+'" alt="Werden Fehlstunden nicht pauschal erfasst, lassen sich die tages- oder fachbezogenen Fehlstunden über diesen Gruppenprozess aufsummieren und als Fehlstundensummen im aktuellen Lernabschnitt hinterlegen." loading="lazy"></a></p><p><em>Werden Fehlstunden nicht pauschal erfasst, lassen sich die tages- oder fachbezogenen Fehlstunden über diesen Gruppenprozess aufsummieren und als Fehlstundensummen im aktuellen Lernabschnitt hinterlegen.</em></p><p>Wenn Sie Fehlstunden tages- oder fachbezogen erfassen, führen Sie <strong>Gruppenprozesse ➜ Noten/Zeugnisvorbereitung ➜ Fehlstundensummen autom. berechnen</strong> aus. Der Prozess summiert die Fehlstunden für jede Person und trägt die Werte unter <strong>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben</strong> in <strong>Ges. Fehlstd.</strong> und <strong>Unentschuldigt</strong> ein. Bei pauschaler Eingabe direkt in diese Summenfelder benötigen Sie diesen Prozess nicht.</p><p>Der Gruppenprozess steht nur zur Verfügung, wenn eine Schülergruppe ausgewählt wurde, bei der eingestellt ist, dass Fehlstunden tages- oder fachbezogen erfasst werden.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noten-einstellungen-fehlstundenerfassung.png"><img src="'+l+'" alt="Wählen Sie, wie die Fehlstunden in der Sek I und Sek II erfasst werden. Hier werden die Fehlstunden in der Sekundarstufe II fachbezogen erfasst, daher steht uns bei Wahl von Sek II-Schülern der Gruppenprozess zur automatischen Aufsummierung der Fehlstunden zur Verfügung." loading="lazy"></a></p><p><em>Wählen Sie, wie die Fehlstunden in der Sek I und Sek II erfasst werden. Hier werden die Fehlstunden in der Sekundarstufe II fachbezogen erfasst, daher steht uns bei Wahl von Sek II-Schülern der Gruppenprozess zur automatischen Aufsummierung der Fehlstunden zur Verfügung.</em></p><p>Diese Einstellung wird unter <em>Verwaltung ➜ Einstellungen ➜ Fächer, Noten</em> im Feld <em>Eingabemodus</em> für Fehlstundenerfassung in jeweils der Sek I und der Sek II gewählt.</p>',9),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),s("Hinweis")]),e("p",null,"Achten Sie darauf, dass"),e("ol",null,[e("li",null,"eine erneute Ausführung des Gruppenprozesses alle individuell vorgenommenen Änderungen bei den Gesamtfehlstunden bei den gewählten Schülern überschreibt."),e("li",null,"Denken Sie daran, dass nach dem Nachtragen von fachbezogenen Fehlstunden die Aufsummierung erneut auszuführen ist, um in Zeugniskonferenzen und auf auf den Zeugnissen die korrekten Fehlstunden vorliegen zu haben.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fehlstunden-Summen_autom._berechnen_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),s(" · Quellrevision 5201.")],-1)])])}const z=r(d,[["render",o]]);export{b as __pageData,z as default};
